import {planningOverlay} from './planning-overlay.js';
import {mountTourStudio} from './tour-studio.js';
import {featuresSVG} from './building-features.js';
import {CATALOG,MATERIALS,uid,round,item,wall,createProject,createFloor,validateProject,floorBounds,floorArea,openingAt,History} from './model.js';
import {StudioScene,thumbnails} from './scene.js';
import {mountCADStudio} from './cad-studio.js';
import {mountLocalWorkspace} from './workspace-client.js';
import {mountInteriorStudio} from './interior-studio.js';
import {mountPlanningStudio} from './planning-studio.js';
let cadStudio=null,localWorkspace=null,interiorStudio=null,planningStudio=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='forma-project-v1';let project,storageProblem=false;
try{const saved=localStorage.getItem(KEY);project=saved?validateProject(JSON.parse(saved)):createProject();}catch{project=createProject();storageProblem=true;}
let floorId=project.floors[0].id,tab='furnish',category='All',search='',view='3d',tool='select',selected=null,cutaway=true,labels=true,light='day',scene=null,thumbs={},planZoom=1,planCenter=null,pendingPoint=null,drag=null,toastTimer,blueprintOpacity=.35;const history=new History();
const floor=()=>project.floors.find(f=>f.id===floorId)||project.floors[0];
const collection=kind=>kind==='item'?'items':kind==='room'?'rooms':'walls';
const selectedObj=()=>selected?floor()[collection(selected.kind)].find(i=>i.id===selected.id):null;
const length=n=>project.units==='ft'?`${(n*3.28084).toFixed(2)} ft`:`${round(n)} m`;
const area=n=>project.units==='ft'?`${(n*10.7639).toFixed(1)} ft²`:`${round(n)} m²`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function save(){project.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(project));$('#save-status').innerHTML='<span class="status-dot"></span> Saved on this device';storageProblem=false;}catch{$('#save-status').textContent='Storage full · export to save';if(!storageProblem)toast('Device storage is unavailable. Export your project to keep your changes.');storageProblem=true;}localWorkspace?.queue(project);}
function commit(fn,{refresh=true}={}){const before=structuredClone(project);try{fn();validateProject(project);}catch(error){project=before;renderAll();toast(error.message);return false;}history.push(before);save();if(refresh)renderAll();return true;}
function renderAll(){if(!project.floors.some(f=>f.id===floorId))floorId=project.floors[0].id;if(selected&&!selectedObj())selected=null;renderHeader();renderPlan();scene?.load(floor(),cutaway);scene?.lighting(light);scene?.updateSelection(selected?.id);renderInspector();updateHistory();if(['blueprint','materials','build'].includes(tab))renderPanel();cadStudio?.refresh();interiorStudio?.refresh();}
function renderHeader(){$('#project-name').innerHTML=esc(project.name)+' <span>⌄</span>';$('#scene-name').textContent=project.name;$('#floor-select').innerHTML=project.floors.map(f=>`<option value="${f.id}" ${f.id===floorId?'selected':''}>${esc(f.name)}</option>`).join('');$('#units').value=project.units;$('#area-status').textContent=area(floorArea(floor()));$('#object-count').textContent=`${floor().items.length+(floor().features?.length||0)+(project.cad?.entities.filter(e=>e.floorId===floorId).length||0)} objects`;}
function updateHistory(){$('#undo-btn').disabled=!history.undoStack.length;$('#redo-btn').disabled=!history.redoStack.length;}
function select(kind,id){selected=id?{kind,id}:null;renderInspector();scene?.updateSelection(id);renderPlan();}
function setView(v){view=v;$('#three-wrap').hidden=v!=='3d'||!scene;$('#plan-wrap').hidden=v!=='2d';$('#webgl-error').hidden=v!=='3d'||!!scene;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#view-chip').textContent=v==='3d'?'LIVE 3D PREVIEW':'EDITABLE FLOOR PLAN';$('#interaction-hint').innerHTML=v==='3d'?'<kbd>Drag</kbd> to orbit <span>·</span> <kbd>Scroll</kbd> to zoom':'<kbd>Drag</kbd> to move <span>·</span> <kbd>W</kbd> walls <span>·</span> <kbd>Esc</kbd> cancel';if(v==='2d')renderPlan();else requestAnimationFrame(()=>scene?.resize());}
function setTool(t){tool=t;pendingPoint=null;if(t!=='select'){setView('2d');selected=null;renderInspector();}if(scene)scene.editMode=t==='select';$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#plan-svg').style.cursor=t==='select'?'default':'crosshair';if(t==='room')toast('Click two opposite corners to draw a room.');if(t==='wall')toast('Click a start point, then an end point. Esc finishes.');if(['door','window'].includes(t))toast(`Click a wall to place a ${t}.`);if(t==='calibrate')toast('Click two points on the blueprint whose distance you know.');renderPlan();if(tab==='build')renderPanel();}
function placeholder(type){return `<svg viewBox="0 0 120 90" xmlns="http://www.w3.org/2000/svg"><ellipse cx="60" cy="72" rx="40" ry="8" fill="#0001"/><path d="m22 37 40-16 37 19-40 19z" fill="#c5b197"/><path d="M22 37v23l37 19V59z" fill="#9c876b"/><path d="m59 59 40-19v22L59 79z" fill="#b8a184"/></svg>`;}
function img(i){return thumbs[i.type]?`<img src="${thumbs[i.type]}" alt="${esc(i.name)}" style="width:100%;height:100%;object-fit:contain"/>`:placeholder(i.type);}
const panelMeta={furnish:['MAKE IT YOURS','Furniture library'],build:['START WITH THE BONES','Build your space'],materials:['A FEELING IN EVERY FINISH','Materials & colors'],lighting:['SET THE MOOD','Light & atmosphere'],blueprint:['FROM PLAN TO POSSIBILITY','Import a blueprint']};
function renderPanel(){if(interiorStudio?.active){interiorStudio.renderPanel();return;}if(cadStudio?.active){cadStudio.renderPanel();return;}const [eyebrow,title]=panelMeta[tab];$('#panel-eyebrow').textContent=eyebrow;$('#panel-title').textContent=title;$('#library-count').hidden=tab!=='furnish';const el=$('#panel-content');
if(tab==='furnish'){el.innerHTML=`<label class="search">${icon('search')}<input id="catalog-search" placeholder="Find something you love…" aria-label="Search furniture" value="${esc(search)}"/></label><div class="chips">${['All','Living','Bedroom','Dining','Kitchen','Bathroom','Decor','Lighting','Office'].map(c=>`<button class="chip ${c===category?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="section-label"><strong>Considered essentials</strong><span>CURATED COLLECTION</span></div><div class="catalog-grid" id="catalog-grid"></div>`;renderCatalog();$('#catalog-search').oninput=e=>{search=e.target.value;renderCatalog();};$$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;renderPanel();});}
if(tab==='build'){el.innerHTML=`<p class="panel-copy">Start with a room. Give it shape, then make it yours. Draw in <strong>2D plan</strong> and see changes in 3D.</p><div class="build-list">${[['select','move','Select & move','Select objects or rooms','V'],['room','grid','Draw a room','Choose two opposite corners','B'],['wall','wall','Draw a wall','Click to start, click to finish','W'],['door','door','Add a doorway','Place an opening in a wall','D'],['window','window','Add a window','Place a window in a wall','N']].map(([t,ic,name,sub,key])=>`<button data-build="${t}" class="build-button ${tool===t?'active':''}">${icon(ic)}<span><strong>${name}</strong><small>${sub}</small></span><kbd>${key}</kbd></button>`).join('')}</div><div class="separator"></div><div class="property-heading">Drawing settings</div><p class="panel-copy">Geometry snaps to a 10 cm grid. Rooms are rectangular; walls can be drawn at any angle.</p><button id="rename-floor" class="button subtle full-width">Rename this floor</button>${project.floors.length>1?'<button id="delete-floor" class="button subtle full-width danger">Delete this floor</button>':''}`;$$('[data-build]').forEach(b=>b.onclick=()=>setTool(b.dataset.build));$('#rename-floor').onclick=()=>nameDialog('Name this floor',floor().name,name=>commit(()=>floor().name=name));$('#delete-floor')?.addEventListener('click',()=>confirmDialog('Delete this floor?','All rooms, walls, and furniture on this floor will be removed.',()=>commit(()=>{project.floors=project.floors.filter(f=>f.id!==floorId);if(project.cad){project.cad.entities=project.cad.entities.filter(e=>e.floorId!==floorId);project.cad.scenes=project.cad.scenes.filter(s=>s.floorId!==floorId);}floorId=project.floors[0].id;selected=null;})));}
if(tab==='materials'){const o=selectedObj();const active=selected?.kind==='room'?o?.material:null;el.innerHTML=`<p class="panel-copy">Select a room to change its floor finish, or select furniture to change its color.</p><div class="material-grid">${MATERIALS.map(m=>`<button class="material-card ${active===m.id?'active':''}" data-material="${m.id}"><div class="material-sample ${m.kind}" style="background-color:${m.color}"></div>${m.name}</button>`).join('')}</div><div class="tip-card"><h4>${icon('palette')}A considered palette</h4><p>Choose a warm foundation, then layer contrasting textures. Select a room in either view to begin.</p></div>`;$$('[data-material]').forEach(b=>b.onclick=()=>applyMaterial(b.dataset.material));}
if(tab==='lighting'){el.innerHTML=`<p class="panel-copy">Explore how your home feels throughout the day.</p><button class="light-card ${light==='day'?'active':''}" data-light="day"><strong>Slow Sunday</strong><span>Soft daylight · warm and natural</span></button><button class="light-card evening ${light==='evening'?'active':''}" data-light="evening"><strong>Golden evening</strong><span>Warm light · a little more atmosphere</span></button><div class="tip-card"><h4>${icon('sun')}A preview of the mood</h4><p>These presets change the scene's daylight. Lamp models are decorative; the preview does not simulate individual lamp lighting.</p></div>`;$$('[data-light]').forEach(b=>b.onclick=()=>{light=b.dataset.light;scene?.lighting(light);renderPanel();});}
if(tab==='blueprint'){const bp=floor().blueprint;el.innerHTML=`<p class="panel-copy">Use Plan lab for calibrated image/PDF detection and reviewed 3D reconstruction. You can also import an image below for manual tracing.</p><button id="open-plan-lab" class="button full-width">Detect and review in Plan lab</button><button id="upload-blueprint" class="upload-area">${icon('upload')}<strong>${bp?'Replace blueprint':'Upload your floor plan'}</strong><small>PNG, JPG or WebP · up to 10 MB<br>PDF page selection is available in Plan lab.</small></button>${bp?`<div class="blueprint-settings"><div class="property-heading">Blueprint scale</div><div class="field-grid"><label class="field">Width (meters)<input id="bp-width" type="number" min=".1" max="100" step=".1" value="${bp.w}"/></label><label class="field">Height (meters)<input id="bp-depth" type="number" min=".1" max="100" step=".1" value="${bp.d}"/></label><label class="field">X position<input id="bp-x" type="number" min="-100" max="100" step=".1" value="${bp.x}"/></label><label class="field">Y position<input id="bp-z" type="number" min="-100" max="100" step=".1" value="${bp.z}"/></label></div><p class="small-label">Opacity</p><input id="bp-opacity" aria-label="Blueprint opacity" type="range" min=".1" max=".9" step=".05" class="slider" value="${blueprintOpacity}"/><button id="calibrate-bp" class="button subtle full-width">${icon('ruler')}Calibrate a known distance</button><button id="remove-bp" class="button subtle full-width danger">Remove blueprint</button></div>`:''}<div class="tip-card"><h4>${icon('ruler')}Accuracy comes first</h4><p>This image-only import is a tracing reference. Plan lab creates uncertain detected drafts that require measurement and geometry review.</p></div>`;$('#open-plan-lab').onclick=()=>planningStudio?.open('import');$('#upload-blueprint').onclick=()=>$('#blueprint-input').click();if(bp){for(const [id,key,min,max] of [['width','w',.1,100],['depth','d',.1,100],['x','x',-100,100],['z','z',-100,100]])$('#bp-'+id).onchange=e=>{const v=Number(e.target.value);if(!Number.isFinite(v)||v<min||v>max){toast('Enter a value within the allowed range.');renderPanel();return;}commit(()=>bp[key]=v);};$('#bp-opacity').oninput=e=>{blueprintOpacity=Number(e.target.value);renderPlan();};$('#remove-bp').onclick=()=>commit(()=>floor().blueprint=null);$('#calibrate-bp').onclick=()=>setTool('calibrate');}}
}
function renderCatalog(){const list=CATALOG.filter(i=>(category==='All'||i.category===category)&&i.name.toLowerCase().includes(search.toLowerCase()));$('#library-count').textContent=list.length;$('#catalog-grid').innerHTML=list.length?list.map((i,n)=>`<button class="catalog-card" data-add="${i.type}" title="Add ${esc(i.name)}"><div class="catalog-image">${img(i)}${n===0&&!search?'<span class="tag-small">STUDIO PICK</span>':''}<span class="add-item">+</span></div><span class="catalog-name">${i.name}</span><span class="catalog-meta">${length(i.w)} × ${length(i.d)}</span></button>`).join(''):'<p class="empty-results">No matches. Try another search.</p>';$$('[data-add]').forEach(b=>b.onclick=()=>addItem(b.dataset.add));}
function addItem(type){const b=floorBounds(floor());let i;commit(()=>{i=item(type,round(b.x+b.w/2),round(b.z+b.d/2));floor().items.push(i);selected={kind:'item',id:i.id};});setTool('select');toast(`${i.name} added. Drag it into place.`);}
function applyMaterial(id){const o=selectedObj();if(!o){toast('Select a room, wall, or furniture item first.');return;}const m=MATERIALS.find(m=>m.id===id);commit(()=>{if(selected.kind==='room')o.material=id;else o.color=m.color;});}
function numberField(key,label,value,{min=-200,max=200,step=.1,wide=false,convert=true}={}){const display=convert&&project.units==='ft'?round(value*3.28084):round(value);return `<label class="field ${wide?'wide':''}">${label}<input data-prop="${key}" data-convert="${convert}" type="number" min="${convert&&project.units==='ft'?round(min*3.28084):min}" max="${convert&&project.units==='ft'?round(max*3.28084):max}" step="${step}" value="${display}"/></label>`;}
function renderInspector(){if(interiorStudio?.active){interiorStudio.renderInspector();return;}if(cadStudio?.active){cadStudio.renderInspector();return;}const o=selectedObj(),el=$('#inspector-content');$('#inspector').classList.toggle('has-selection',!!o);if(!o){el.innerHTML=`<span class="eyebrow">YOUR DESIGN AT A GLANCE</span><h2>Made for your everyday.</h2><div class="overview-hero"><span class="eyebrow">THE SUNDAY HOUSE COLLECTION</span><h3>Room to live.<br>Space to dream.</h3><p>Natural textures. Quiet colors.<br>A home that feels like you.</p></div><div class="property-heading">This floor ${icon('layers')}</div><div class="overview-stat"><span>Total room area</span><strong>${area(floorArea(floor()))}</strong></div><div class="overview-stat"><span>Furniture & decor</span><strong>${floor().items.length} pieces</strong></div><div class="overview-stat"><span>Floors</span><strong>${project.floors.length}</strong></div><div class="separator"></div><div class="property-heading">Your rooms <span>${floor().rooms.length} SPACES</span></div><div class="room-list">${floor().rooms.map(r=>`<button class="room-row" data-select-room="${r.id}"><span class="room-color" style="background:${MATERIALS.find(m=>m.id===r.material)?.color}"></span>${esc(r.name)}<span class="room-area">${area(r.w*r.d)}</span></button>`).join('')}</div><div class="tip-card"><h4>${icon('spark')}Make room for possibility</h4><p>Choose something from the library, then move, rotate, or recolor it to find your perfect fit.</p><button id="open-guide">Take a quick tour ${icon('arrow')}</button></div><div class="separator"></div><button id="budget-btn" class="button subtle full-width">View furniture estimate</button><p class="inspector-empty">${localWorkspace?.online?'Projects save on this PC, with browser recovery. Open PC workspace for history.':'Projects save to this browser. Start the local server for PC workspace storage.'} Export a project file for a portable backup.</p>`;$$('[data-select-room]').forEach(b=>b.onclick=()=>select('room',b.dataset.selectRoom));$('#open-guide').onclick=showGuide;$('#budget-btn').onclick=showBudget;return;}
const kind=selected.kind,unit=project.units==='ft'?'ft':'m';el.innerHTML=`<div class="property-heading"><span class="eyebrow">${kind==='item'?'OBJECT':kind==='room'?'ROOM':'WALL'} PROPERTIES</span><button id="deselect" class="icon-btn" title="Deselect" aria-label="Deselect">${icon('close')}</button></div>${kind==='item'?`<div class="inspector-preview">${img(o)}<span class="preview-tag">${esc(o.category.toUpperCase())} COLLECTION</span></div>`:''}<div class="detail-title"><h3>${esc(o.name||(kind==='wall'?'Wall':'Room'))}</h3></div><p class="detail-subtitle">${kind==='item'?'A considered detail. Make it your own.':kind==='room'?'Set the dimensions. Find your flow.':'Build a strong foundation for your space.'}</p>${kind!=='wall'?`<label class="field">Name<input id="object-name" maxlength="80" value="${esc(o.name)}"/></label><div class="separator"></div>`:''}<div class="property-heading">Dimensions <span>${unit.toUpperCase()}</span></div><div class="field-grid">${kind==='wall'?numberField('height','Height',o.height,{min:.2,max:10})+numberField('thickness','Thickness',o.thickness,{min:.02,max:1,step:.01}):numberField('w','Width',o.w,{min:.2,max:kind==='item'?20:100})+numberField('d','Depth',o.d,{min:.2,max:kind==='item'?20:100})+(kind==='item'?numberField('h','Height',o.h,{min:.1,max:10}):'')}</div><div class="separator"></div><div class="property-heading">Position <span>${unit.toUpperCase()}</span></div><div class="field-grid">${kind==='wall'?numberField('x1','Start X',o.x1)+numberField('z1','Start Y',o.z1)+numberField('x2','End X',o.x2)+numberField('z2','End Y',o.z2):numberField('x','X',o.x)+numberField('z','Y',o.z)+(kind==='item'?numberField('rotation','Rotation (°)',o.rotation,{min:-3600,max:3600,step:15,wide:true,convert:false}):'')}</div><div class="separator"></div><div class="property-heading">${kind==='room'?'Floor finish':'Color & finish'}</div><div class="swatches">${MATERIALS.map(m=>`<button data-finish="${m.id}" class="swatch ${kind==='room'?o.material===m.id?'active':'':o.color===m.color?'active':''}" style="background:${m.color}" title="${m.name}" aria-label="Apply ${m.name}"></button>`).join('')}</div>${kind!=='room'?`<label class="field color-field" style="margin-top:17px">Custom color<input id="custom-color" type="color" value="${o.color}"/></label>`:`<p class="selected-note">${MATERIALS.find(m=>m.id===o.material)?.name||'Natural oak'} · ${area(o.w*o.d)}</p>`}${kind==='wall'?`<div class="separator"></div><div class="property-heading">Openings</div>${o.openings.map(op=>`<div class="opening-row"><span>${esc(op.type)} · ${length(op.width)}</span><button data-remove-opening="${op.id}" aria-label="Remove ${op.type}">×</button></div>`).join('')||'<p class="selected-note">No openings. Use Build to add a door or window.</p>'}`:''}<div class="separator"></div><div class="object-actions">${kind==='item'?`<button id="rotate-object">${icon('rotate')}Rotate 90°</button><button id="duplicate-object">${icon('copy')}Duplicate</button>`:kind==='room'?`<button id="room-walls">${icon('wall')}Add walls</button><button id="duplicate-object">${icon('copy')}Duplicate</button>`:`<button id="wall-door">${icon('door')}Door</button><button id="wall-window">${icon('window')}Window</button>`}<button id="delete-object" class="danger">${icon('trash')}Delete</button></div><p class="inspector-empty">${kind==='item'?'Drag to position in either view. Rotate with R; duplicate with Ctrl+D.':kind==='room'?'Room dimensions control the floor surface. Existing walls stay independent; edit wall endpoints separately.':'Openings remain attached to this wall.'}</p>`;
$('#deselect').onclick=()=>select(null,null);$('#object-name')?.addEventListener('change',e=>{const name=e.target.value.trim();if(name)commit(()=>o.name=name.slice(0,80));});$$('[data-prop]').forEach(inp=>inp.onchange=()=>{let v=Number(inp.value);if(!Number.isFinite(v)||v<Number(inp.min)||v>Number(inp.max)){toast('Enter a value within the allowed range.');renderInspector();return;}if(inp.dataset.convert==='true'&&project.units==='ft')v/=3.28084;const key=inp.dataset.prop;if(round(o[key])===round(v))return;const candidate={...o,[key]:round(v)};if(kind==='wall'){const L=Math.hypot(candidate.x2-candidate.x1,candidate.z2-candidate.z1);if(L<.1||o.openings.some(op=>op.offset+op.width/2>L)){toast('This wall must remain long enough for its openings.');renderInspector();return;}}if(kind==='room'&&roomOverlaps(candidate,o.id)){toast('Room surfaces cannot overlap. Move or resize adjacent rooms first.');renderInspector();return;}commit(()=>o[key]=round(v));});$$('[data-finish]').forEach(b=>b.onclick=()=>applyMaterial(b.dataset.finish));$('#custom-color')?.addEventListener('change',e=>commit(()=>o.color=e.target.value));$('#rotate-object')?.addEventListener('click',rotateObject);$('#duplicate-object')?.addEventListener('click',duplicateObject);$('#delete-object').onclick=deleteObject;$('#room-walls')?.addEventListener('click',()=>{commit(()=>addRoomWalls(o));toast('Walls added around this room.');});$$('[data-remove-opening]').forEach(b=>b.onclick=()=>commit(()=>o.openings=o.openings.filter(op=>op.id!==b.dataset.removeOpening)));$('#wall-door')?.addEventListener('click',()=>setTool('door'));$('#wall-window')?.addEventListener('click',()=>setTool('window'));}
function roomOverlaps(r,except){return floor().rooms.some(a=>a.id!==except&&r.x<a.x+a.w-.01&&r.x+r.w>a.x+.01&&r.z<a.z+a.d-.01&&r.z+r.d>a.z+.01);}
function addRoomWalls(r){for(const [x1,z1,x2,z2] of [[r.x,r.z,r.x+r.w,r.z],[r.x+r.w,r.z,r.x+r.w,r.z+r.d],[r.x+r.w,r.z+r.d,r.x,r.z+r.d],[r.x,r.z+r.d,r.x,r.z]]){if(!floor().walls.some(w=>(Math.hypot(w.x1-x1,w.z1-z1)<.02&&Math.hypot(w.x2-x2,w.z2-z2)<.02)||(Math.hypot(w.x2-x1,w.z2-z1)<.02&&Math.hypot(w.x1-x2,w.z1-z2)<.02)))floor().walls.push(wall(x1,z1,x2,z2));}}
function rotateObject(){const o=selectedObj();if(selected?.kind!=='item')return;commit(()=>o.rotation=(o.rotation+90)%360);}
function duplicateObject(){const o=selectedObj();if(!o||selected.kind==='wall')return;const copy=structuredClone(o);copy.id=uid();copy.x+=.4;copy.z+=.4;if(selected.kind==='room'){copy.x=o.x+o.w+.4;copy.name=o.name+' copy';if(roomOverlaps(copy)){toast('Not enough space next to this room for a copy.');return;}}commit(()=>{floor()[collection(selected.kind)].push(copy);selected.id=copy.id;});toast('Duplicated.');}
function deleteObject(){if(!selected)return;const kind=selected.kind,id=selected.id;commit(()=>{floor()[collection(kind)]=floor()[collection(kind)].filter(o=>o.id!==id);selected=null;});toast(kind==='room'?'Room surface removed. Its walls remain editable.':'Removed from your design.');}
function planBox(){const b=cadStudio?.planBounds()||floorBounds(floor());const bp=floor().blueprint;if(bp){const x=Math.min(b.x,bp.x),z=Math.min(b.z,bp.z);b.w=Math.max(b.x+b.w,bp.x+bp.w)-x;b.d=Math.max(b.z+b.d,bp.z+bp.d)-z;b.x=x;b.z=z;}const pad=1.2,w=(b.w+pad*2)/planZoom,d=(b.d+pad*2)/planZoom,c=planCenter||{x:b.x+b.w/2,z:b.z+b.d/2};return{x:c.x-w/2,z:c.z-d/2,w,d};}
function roomSVG(r){const m=MATERIALS.find(m=>m.id===r.material)||MATERIALS[0],active=selected?.id===r.id;return `<g data-kind="room" data-id="${r.id}" class="movable"><rect x="${r.x}" y="${r.z}" width="${r.w}" height="${r.d}" fill="${m.color}" fill-opacity="${floor().blueprint ? 0.12 : 1}" stroke="${active?'#9b6ccd':'#958d7e'}" stroke-width="${active?.055:.012}"/>${labels?`<text x="${r.x+r.w/2}" y="${r.z+r.d/2-.12}" text-anchor="middle" font-family="sans-serif" font-size=".19" fill="#56544d" pointer-events="none">${esc(r.name)}</text><text x="${r.x+r.w/2}" y="${r.z+r.d/2+.15}" text-anchor="middle" font-family="sans-serif" font-size=".14" fill="#7b7669" pointer-events="none">${area(r.w*r.d)}</text>`:''}</g>`;}
function wallSVG(w){const L=Math.hypot(w.x2-w.x1,w.z2-w.z1),angle=Math.atan2(w.z2-w.z1,w.x2-w.x1)*180/Math.PI;return `<g data-kind="wall" data-id="${w.id}" transform="translate(${w.x1} ${w.z1}) rotate(${angle})"><line x1="0" y1="0" x2="${L}" y2="0" stroke="${selected?.id===w.id?'#a57adb':'#565953'}" stroke-width="${w.thickness}"/><line x1="0" y1="0" x2="${L}" y2="0" stroke="transparent" stroke-width=".28"/>${w.openings.map(o=>`<g pointer-events="none"><line x1="${o.offset-o.width/2}" y1="0" x2="${o.offset+o.width/2}" y2="0" stroke="${o.type==='window'?'#8db5b5':'#eee9df'}" stroke-width="${w.thickness+.025}"/>${o.type==='door'?`<path d="M${o.offset-o.width/2} 0v${o.width}a${o.width} ${o.width} 0 0 0 ${o.width} -${o.width}" fill="none" stroke="#736c60" stroke-width=".018"/>`:`<line x1="${o.offset-o.width/2}" y1="0" x2="${o.offset+o.width/2}" y2="0" stroke="#edf8f6" stroke-width=".035"/>`}</g>`).join('')}</g>`;}
function furnitureSVG(i){const {w,d,type:t}=i,sel=selected?.id===i.id;const rect=(x,y,ww,dd,fill,rx=.04)=>`<rect x="${x}" y="${y}" width="${ww}" height="${dd}" rx="${rx}" fill="${fill}" stroke="#645d522a" stroke-width=".015"/>`;let shape=rect(-w/2,-d/2,w,d,i.color);if(t==='rug')shape=`<rect x="${-w/2}" y="${-d/2}" width="${w}" height="${d}" rx=".025" fill="${i.color}" stroke="#b1a087" stroke-dasharray=".06 .04" stroke-width=".025"/>`;else if(['sofa','chair'].includes(t))shape+=rect(-w/2,-d/2,w,.17,'#a5ac98')+rect(-w/2,-d/2,.16,d,'#a5ac98')+rect(w/2-.16,-d/2,.16,d,'#a5ac98')+Array.from({length:t==='sofa'?3:1},(_,k)=>rect(-w/2+.2+k*(w-.4)/(t==='sofa'?3:1),-.19,(w-.43)/(t==='sofa'?3:1),d*.6,i.color)).join('');else if(t==='bed')shape+=rect(-w/2+.06,-d/2+.07,w-.12,.4,'#efebe2')+rect(-w/2+.04,d*.1,w-.08,.48,'#9caa9e');else if(t==='plant')shape=`<circle r="${w/2}" fill="#8b9e79" stroke="#5f7555" stroke-width=".04"/><path d="M0 -.3V.3M-.3 0H.3m-.2-.2.4.4m-.4 0 .4-.4" stroke="#536b49" stroke-width=".025"/>`;else if(t==='lamp')shape=`<circle r="${w/2}" fill="${i.color}" stroke="#73695d" stroke-width=".025"/>`;else if(t==='bath')shape+=rect(-w/2+.12,-d/2+.1,w-.24,d-.2,'#bcd0cf',.15);else if(t==='toilet')shape+=`<ellipse cy=".08" rx="${w*.4}" ry="${d*.3}" fill="#fff" stroke="#b1b3a8" stroke-width=".02"/>`;return `<g data-kind="item" data-id="${i.id}" class="movable" transform="translate(${i.x} ${i.z}) rotate(${i.rotation})">${shape}${sel?`<rect x="${-w/2-.055}" y="${-d/2-.055}" width="${w+.11}" height="${d+.11}" rx=".035" fill="none" stroke="#9c6aca" stroke-width=".035"/><circle cx="${w/2+.055}" cy="${d/2+.055}" r=".055" fill="#fff" stroke="#9c6aca" stroke-width=".025"/>`:''}</g>`;}
function planMarkup(exporting=false){const f=floor(),b=planBox(),bp=f.blueprint;return `<defs><pattern id="dots" width=".5" height=".5" patternUnits="userSpaceOnUse"><circle cx=".02" cy=".02" r=".009" fill="#8d857b40"/></pattern></defs><rect x="${b.x-50}" y="${b.z-50}" width="${b.w+100}" height="${b.d+100}" fill="#eeeae1"/><rect x="${b.x-50}" y="${b.z-50}" width="${b.w+100}" height="${b.d+100}" fill="url(#dots)"/>${bp?`<image href="${bp.src}" x="${bp.x}" y="${bp.z}" width="${bp.w}" height="${bp.d}" opacity="${blueprintOpacity}" preserveAspectRatio="none"/>`:''}${f.rooms.map(roomSVG).join('')}${featuresSVG(f)}${planningOverlay(project,f)}${f.items.filter(i=>i.type==='rug').map(furnitureSVG).join('')}${f.walls.map(wallSVG).join('')}${f.items.filter(i=>i.type!=='rug').map(furnitureSVG).join('')}${!exporting&&pendingPoint?`<circle cx="${pendingPoint.x}" cy="${pendingPoint.z}" r=".075" fill="#a074ce" stroke="#fff" stroke-width=".025"/><g id="draw-preview"></g>`:''}`;}
function renderPlan(){const b=planBox();$('#plan-svg').setAttribute('viewBox',`${b.x} ${b.z} ${b.w} ${b.d}`);$('#plan-svg').innerHTML=planMarkup();cadStudio?.drawPlan();}
function svgPoint(e,snap=true){const svg=$('#plan-svg'),point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());return{x:snap?Math.round(point.x*10)/10:point.x,z:snap?Math.round(point.y*10)/10:point.y};}
function planDown(e){if(e.button!==0)return;const p=svgPoint(e),target=e.target.closest('[data-id]');if(tool==='select'){if(target){const kind=target.dataset.kind,id=target.dataset.id;selected={kind,id};renderInspector();scene?.updateSelection(id);const o=selectedObj();if(kind==='item'||kind==='room'){drag={id,kind,start:svgPoint(e,false),ox:o.x,oz:o.z,moved:false,before:JSON.stringify(project)};$('#plan-svg').setPointerCapture(e.pointerId);}renderPlan();}else select(null,null);return;}
if(['door','window'].includes(tool)){let w=target?.dataset.kind==='wall'?floor().walls.find(w=>w.id===target.dataset.id):null;if(!w){let dist=.35;for(const ww of floor().walls){const dx=ww.x2-ww.x1,dz=ww.z2-ww.z1,L=Math.hypot(dx,dz),t=Math.max(0,Math.min(1,((p.x-ww.x1)*dx+(p.z-ww.z1)*dz)/(L*L))),dd=Math.hypot(p.x-ww.x1-t*dx,p.z-ww.z1-t*dz);if(dd<dist){dist=dd;w=ww;}}}if(!w){toast('Click directly on a wall.');return;}const opening=openingAt(w,p.x,p.z,tool);if(!opening){toast('This opening needs more free space on the wall.');return;}commit(()=>{w.openings.push(opening);selected={kind:'wall',id:w.id};});return;}
if(!pendingPoint){pendingPoint=p;renderPlan();return;}const start=pendingPoint;
if(tool==='calibrate'){const measured=Math.hypot(p.x-start.x,p.z-start.z);pendingPoint=null;if(measured<.05){toast('Choose two different points.');return;}const bp=floor().blueprint;if(!bp){setTool('select');return;}numberDialog('Set the known distance','Enter the actual distance between those points in meters.',measured,.05,100,value=>{const ratio=value/measured;if(bp.w*ratio>100||bp.d*ratio>100){toast('That scale exceeds the 100 m blueprint size limit.');return;}commit(()=>{bp.x=start.x+(bp.x-start.x)*ratio;bp.z=start.z+(bp.z-start.z)*ratio;bp.w=round(bp.w*ratio);bp.d=round(bp.d*ratio);});setTool('select');toast('Blueprint scale updated. Existing geometry stays unchanged.');});return;}
if(tool==='wall'){if(Math.hypot(start.x-p.x,start.z-p.z)<.2)return;commit(()=>floor().walls.push(wall(start.x,start.z,p.x,p.z)));pendingPoint=p;renderPlan();return;}
if(tool==='room'){const r={id:uid(),name:'New room',x:Math.min(start.x,p.x),z:Math.min(start.z,p.z),w:round(Math.abs(p.x-start.x)),d:round(Math.abs(p.z-start.z)),material:'oak'};if(r.w<.5||r.d<.5){toast('A room needs to be at least 0.5 m in each direction.');return;}if(roomOverlaps(r)){toast('This room overlaps another room. Choose an empty area.');pendingPoint=null;renderPlan();return;}pendingPoint=null;commit(()=>{floor().rooms.push(r);addRoomWalls(r);selected={kind:'room',id:r.id};});setTool('select');}}
function planMove(e){const p=svgPoint(e);if(drag){const o=selectedObj();if(!o)return;const raw=svgPoint(e,false),x=round(Math.round((drag.ox+raw.x-drag.start.x)*10)/10),z=round(Math.round((drag.oz+raw.z-drag.start.z)*10)/10);if(Math.abs(x)>200||Math.abs(z)>200)return;if(drag.kind==='room'&&roomOverlaps({...o,x,z},o.id))return;o.x=x;o.z=z;drag.moved=x!==drag.ox||z!==drag.oz;renderPlan();return;}const preview=$('#draw-preview');if(preview&&pendingPoint){preview.innerHTML=tool==='room'?`<rect x="${Math.min(p.x,pendingPoint.x)}" y="${Math.min(p.z,pendingPoint.z)}" width="${Math.abs(p.x-pendingPoint.x)}" height="${Math.abs(p.z-pendingPoint.z)}" fill="#b89cda40" stroke="#9b74bb" stroke-width=".035" stroke-dasharray=".1 .06"/>`:`<line x1="${pendingPoint.x}" y1="${pendingPoint.z}" x2="${p.x}" y2="${p.z}" stroke="#a17dc3" stroke-width=".06" stroke-dasharray=".1 .06"/>`;}}
function planUp(){if(!drag)return;if(drag.moved){history.undoStack.push(drag.before);if(history.undoStack.length>history.limit)history.undoStack.shift();history.redoStack=[];save();}drag=null;renderAll();}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function nameDialog(title,value,cb){modal(`<span class="eyebrow">YOUR SPACE, YOUR WORDS</span><h2>${esc(title)}</h2><form id="name-form"><label class="field">Name<input id="dialog-name" maxlength="80" required value="${esc(value)}"/></label><div class="dialog-actions"><button type="submit" class="button primary">Save name ${icon('check')}</button></div></form>`);$('#name-form').onsubmit=e=>{e.preventDefault();const v=$('#dialog-name').value.trim();if(!v)return;closeModal();cb(v);};$('#dialog-name').focus();$('#dialog-name').select();}
function numberDialog(title,desc,value,min,max,cb){modal(`<span class="eyebrow">MEASURE TWICE. DESIGN ONCE.</span><h2>${title}</h2><p>${desc}</p><form id="number-form"><label class="field">Distance in meters<input id="dialog-number" type="number" step=".01" min="${min}" max="${max}" required value="${round(value)}"/></label><div class="dialog-actions"><button class="button primary" type="submit">Apply scale</button></div></form>`);$('#number-form').onsubmit=e=>{e.preventDefault();const v=Number($('#dialog-number').value);if(!Number.isFinite(v)||v<min||v>max)return;closeModal();cb(v);};}
function confirmDialog(title,desc,cb){modal(`<span class="eyebrow">PROJECT SETTINGS</span><h2>${title}</h2><p>${desc}</p><div class="dialog-actions"><button id="confirm-action" class="button primary">Continue</button><button id="cancel-action" class="button subtle">Cancel</button></div>`);$('#confirm-action').onclick=()=>{closeModal();cb();};$('#cancel-action').onclick=closeModal;}
function download(data,name,type='application/json'){const blob=typeof data==='string'&&data.startsWith('data:')?null:new Blob([data],{type});const url=blob?URL.createObjectURL(blob):data,a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();if(blob)setTimeout(()=>URL.revokeObjectURL(url),3000);}
const slug=()=>project.name.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'forma-home';
function exportProject(){download(JSON.stringify(project,null,2),`${slug()}.forma.json`);toast('Project exported. Keep this file as your backup.');}
async function exportPlan(){const b=planBox();const markup=`<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="2000" height="1500" viewBox="${b.x} ${b.z} ${b.w} ${b.d}">${$('#plan-svg').innerHTML}</svg>`;const blob=new Blob([markup],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),image=new Image();image.onload=()=>{const c=document.createElement('canvas');c.width=2000;c.height=1500;const ctx=c.getContext('2d');ctx.fillStyle='#eeeae1';ctx.fillRect(0,0,2000,1500);ctx.drawImage(image,0,0);try{download(c.toDataURL('image/png'),`${slug()}-floor-plan.png`);toast('Floor plan exported at 2000 × 1500.');}catch{toast('Could not export the plan. Try exporting your project file.');}URL.revokeObjectURL(url);};image.onerror=()=>{URL.revokeObjectURL(url);toast('Could not render the floor plan image.');};image.src=url;}
function captureView(){if(view==='2d'){exportPlan();return;}if(!scene){toast('3D is unavailable. Export a 2D floor plan instead.');return;}download(scene.capture(),`${slug()}-3d-view.png`);toast('3D preview captured.');}
function exportSchedule(){const rows=[['Floor','Furniture','Width (m)','Depth (m)','Quantity','Reference price (USD)']];for(const f of project.floors)for(const i of f.items)rows.push([f.name,i.name,i.w,i.d,1,i.price]);download(rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),`${slug()}-furniture.csv`,'text/csv');toast('Furniture schedule exported.');}
function showExport(){modal(`<span class="eyebrow">TAKE YOUR IDEAS WITH YOU</span><h2>A little closer to home.</h2><p>Save your design, share a preview, or bring your furniture list along.</p><div class="export-options"><button class="export-option" id="export-json">${icon('folder')}<span><strong>Editable project</strong><small>JSON · backup or reopen on another device</small></span></button><button class="export-option" id="export-plan">${icon('grid')}<span><strong>2D floor plan</strong><small>PNG · 2000 × 1500 · current floor</small></span></button><button class="export-option" id="export-image">${icon('camera')}<span><strong>Current view</strong><small>PNG · browser preview, not an offline photorealistic render</small></span></button><button class="export-option" id="export-glb">${icon('cube')}<span><strong>Editable 3D model</strong><small>GLB · current floor, geometry and materials</small></span></button><button class="export-option" id="export-csv">${icon('ruler')}<span><strong>Furniture schedule</strong><small>CSV · all floors, dimensions, and reference prices</small></span></button></div>`);$('#export-json').onclick=exportProject;$('#export-plan').onclick=exportPlan;$('#export-image').onclick=captureView;$('#export-csv').onclick=exportSchedule;}
function showProjects(){modal(`<span class="eyebrow">YOUR PERSONAL WORKSPACE</span><h2>Every home starts here.</h2><p>Your current project saves automatically to this browser. Download an editable backup before clearing browser data.</p><div class="project-option">${icon('home')}<div><strong>${esc(project.name)}</strong><small>${project.floors.length} floor(s) · ${area(project.floors.reduce((n,f)=>n+floorArea(f),0))}</small></div><button id="rename-project" class="button subtle">Rename</button></div><div class="export-options"><button id="load-project" class="export-option">${icon('upload')}<span><strong>Open a Hestia 2.0 project</strong><small>Import an editable .forma.json backup</small></span></button><button id="blank-project" class="export-option">${icon('plus')}<span><strong>Start a blank home</strong><small>An empty canvas for your next idea</small></span></button><button id="sample-project" class="export-option">${icon('spark')}<span><strong>Open The Sunday House</strong><small>Explore the furnished sample home</small></span></button></div><div class="dialog-actions"><button id="backup-project" class="button primary">${icon('download')}Download backup</button></div>`);$('#rename-project').onclick=()=>nameDialog('Give your home a name',project.name,n=>commit(()=>project.name=n));$('#backup-project').onclick=exportProject;$('#load-project').onclick=()=>$('#project-input').click();const replace=(sample)=>confirmDialog('Start a new project?','This replaces the project on this device. Download a backup first if you want to keep your current work.',()=>{history.push(project);project=createProject();if(!sample){project.name='My new home';project.floors=[createFloor('Ground floor',false)];}floorId=project.floors[0].id;selected=null;planZoom=1;planCenter=null;pendingPoint=null;save();renderAll();scene?.home();toast('Your new canvas is ready.');});$('#blank-project').onclick=()=>replace(false);$('#sample-project').onclick=()=>replace(true);}
function showGuide(){modal(`<span class="eyebrow">WELCOME TO FORMA</span><h2>Make yourself at home.</h2><p>A few simple moves are all it takes to start making this space your own.</p><div class="help-step"><b>1</b><div><strong>Start with the space</strong>Use the furnished sample, or open Project → Start a blank home. Import a blueprint image and calibrate a known distance.</div></div><div class="help-step"><b>2</b><div><strong>Build in 2D, explore in 3D</strong>Click two corners to draw a room. Add walls, doors, and windows. Select anything to adjust its dimensions.</div></div><div class="help-step"><b>3</b><div><strong>Layer in your personality</strong>Add furniture from the library. Drag pieces in either view, rotate them, and try different colors and materials.</div></div><div class="help-step"><b>4</b><div><strong>Keep your ideas</strong>Capture a view or export a plan. Download an editable project file to keep a permanent backup.</div></div><div class="dialog-actions"><button id="guide-done" class="button primary">Let's make room ${icon('arrow')}</button></div>`);$('#guide-done').onclick=closeModal;}
function showHelp(){modal(`<span class="eyebrow">A FEW HELPFUL SHORTCUTS</span><h2>Less searching. More designing.</h2><div class="shortcut-list">${[['V','Select / move'],['W','Draw walls'],['B','Draw a room'],['D','Place a door'],['N','Place a window'],['R','Rotate furniture'],['Delete','Remove selected'],['Esc','Cancel / deselect'],['Ctrl Z','Undo'],['Ctrl Shift Z','Redo'],['Ctrl D','Duplicate'],['Ctrl S','Save locally']].map(([key,s])=>`<span><kbd>${key}</kbd>${s}</span>`).join('')}</div><p>3D: drag a furniture piece to move it; drag empty space to orbit. Right-drag pans the camera. Scroll zooms.</p><p>This local beta supports manual blueprint tracing and browser preview captures. Open Explore for a local walkthrough, reference finishes and AI render connections. Automatic blueprint recognition, cloud accounts and shared editing are not connected.</p><div class="dialog-actions"><button id="help-guide" class="button primary">Open the quick tour</button></div>`);$('#help-guide').onclick=showGuide;}
function showBudget(){const all=project.floors.flatMap(f=>f.items),rows=CATALOG.map(c=>({name:c.name,count:all.filter(i=>i.type===c.type).length,total:all.filter(i=>i.type===c.type).reduce((n,i)=>n+i.price,0)})).filter(r=>r.count),total=all.reduce((n,i)=>n+i.price,0);modal(`<span class="eyebrow">THE DETAILS ADD UP</span><h2>Furniture estimate</h2><p>Illustrative reference prices in USD for planning only. These are not retailer quotes and exclude materials, labor, taxes, and delivery.</p><table class="budget-table"><thead><tr><th>ITEM</th><th>QTY</th><th>REFERENCE USD</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name}</td><td>${r.count}</td><td>$${r.total.toLocaleString()}</td></tr>`).join('')}<tr><td><strong>Total</strong></td><td>${all.length}</td><td><strong>$${total.toLocaleString()}</strong></td></tr></tbody></table><div class="dialog-actions"><button id="budget-export" class="button primary">${icon('download')}Export schedule</button></div>`);$('#budget-export').onclick=exportSchedule;}
async function loadBlueprint(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Choose a PNG, JPG, or WebP image smaller than 10 MB.');return;}const url=URL.createObjectURL(file),image=new Image();image.onerror=()=>{URL.revokeObjectURL(url);toast('This image could not be opened.');};image.onload=()=>{const canvas=document.createElement('canvas'),ratio=Math.min(1,1600/Math.max(image.width,image.height));canvas.width=Math.round(image.width*ratio);canvas.height=Math.round(image.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const src=canvas.toDataURL('image/jpeg',.85),w=12,d=round(12*image.height/image.width);if(d>100||d<.1){URL.revokeObjectURL(url);toast('This image has unsupported proportions. Crop it to the floor plan.');return;}commit(()=>floor().blueprint={src,x:0,z:0,w,d});URL.revokeObjectURL(url);planZoom=1;planCenter=null;setView('2d');setTool('select');toast('Blueprint imported. Calibrate its scale before tracing.');};image.src=url;}
function undo(){const prev=history.undo(project);if(!prev)return;project=prev;selected=null;pendingPoint=null;save();renderAll();}
function redo(){const next=history.redo(project);if(!next)return;project=next;selected=null;pendingPoint=null;save();renderAll();}
$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;$$('[data-tab]').forEach(btn=>btn.classList.toggle('active',btn===b));renderPanel();});$$('[data-view]').forEach(b=>b.onclick=()=>{setTool('select');setView(b.dataset.view);});$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));
$('#floor-select').onchange=e=>{floorId=e.target.value;selected=null;pendingPoint=null;planZoom=1;planCenter=null;renderAll();scene?.home();};$('#add-floor').onclick=()=>{nameDialog('Add a new floor',`Floor ${project.floors.length+1}`,name=>{commit(()=>{const f=createFloor(name,false);f.elevation=project.floors.length*2.9;project.floors.push(f);floorId=f.id;selected=null;planZoom=1;});setTool('room');});};$('#units').onchange=e=>{commit(()=>project.units=e.target.value);renderPanel();};$('#walls-btn').onclick=()=>{cutaway=!cutaway;$('#walls-btn').classList.toggle('active',cutaway);$('#walls-btn span').textContent=cutaway?'Cutaway':'Full walls';scene?.load(floor(),cutaway);};$('#labels-btn').onclick=()=>{labels=!labels;$('#labels-btn').classList.toggle('active',labels);renderPlan();};$('#undo-btn').onclick=undo;$('#redo-btn').onclick=redo;
$('#project-name').onclick=showProjects;$('#projects-btn').onclick=showProjects;$('#guide-btn').onclick=showGuide;$('#help-btn').onclick=showHelp;$('#export-btn').onclick=showExport;$('#capture-btn').onclick=captureView;$('#close-modal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('#fallback-2d').onclick=()=>setView('2d');
$('#reset-camera').onclick=$('#home-camera').onclick=()=>{planZoom=1;planCenter=null;renderPlan();scene?.home();};function zoom(factor){if(view==='2d'){planZoom=Math.max(.3,Math.min(5,planZoom*factor));renderPlan();}else if(scene){const c=scene.controls.target;scene.camera.position.sub(c).multiplyScalar(1/factor).add(c);scene.controls.update();}}$('#zoom-in').onclick=()=>zoom(1.2);$('#zoom-out').onclick=()=>zoom(1/1.2);$('#fullscreen-btn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.editor').requestFullscreen();scene?.resize();}catch{toast('Fullscreen is unavailable in this browser.');}};
$('#plan-svg').addEventListener('pointerdown',planDown);$('#plan-svg').addEventListener('pointermove',planMove);$('#plan-svg').addEventListener('pointerup',planUp);$('#plan-svg').addEventListener('pointercancel',()=>{if(drag){project=JSON.parse(drag.before);drag=null;renderAll();}});$('#plan-svg').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.08:1/1.08);},{passive:false});$('#blueprint-input').onchange=e=>{loadBlueprint(e.target.files[0]);e.target.value='';};$('#project-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>12*1024*1024){toast('Project files must be smaller than 12 MB.');return;}try{const imported=validateProject(JSON.parse(await file.text()));confirmDialog('Open this project?','This replaces your current local project. Export a backup first if you need to keep it.',()=>{history.push(project);project=imported;floorId=project.floors[0].id;selected=null;pendingPoint=null;planZoom=1;save();renderAll();scene?.home();toast('Your project is ready.');});}catch(err){toast(err.message==='Unexpected end of JSON input'?'This project file is incomplete.':err.message);}};
document.addEventListener('focusout',e=>{if(e.target.matches('[data-prop]'))e.target.onchange?.();});
document.addEventListener('keydown',e=>{if($('#modal').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const key=e.key.toLowerCase();if(e.ctrlKey||e.metaKey){if(['z','y','s','d'].includes(key))e.preventDefault();if(key==='z')e.shiftKey?redo():undo();if(key==='y')redo();if(key==='s'){save();toast(storageProblem?'Export your project to keep your changes.':'Saved on this device.');}if(key==='d')duplicateObject();return;}if(key==='escape'){pendingPoint=null;setTool('select');select(null,null);}if(key==='v')setTool('select');if(key==='w')setTool('wall');if(key==='b')setTool('room');if(key==='d')setTool('door');if(key==='n')setTool('window');if(key==='r')rotateObject();if(['delete','backspace'].includes(key)){e.preventDefault();deleteObject();}});
renderHeader();renderPanel();renderInspector();renderPlan();updateHistory();
try{scene=new StudioScene($('#three-canvas'),(kind,id)=>select(kind,id),(id,x,z)=>{const o=floor().items.find(i=>i.id===id);if(o)commit(()=>{o.x=round(Math.max(-200,Math.min(200,x)));o.z=round(Math.max(-200,Math.min(200,z)));});});scene.editMode=true;scene.load(floor(),cutaway);scene.home();setTimeout(()=>{try{thumbs=thumbnails(CATALOG);if(tab==='furnish')renderCatalog();renderInspector();}catch{}},100);}catch(err){console.warn('3D unavailable:',err);setView('2d');toast('3D is unavailable here. The 2D editor is ready.');}
if(storageProblem)toast('Your previous project could not be read. Import an exported backup if you have one.');
window.addEventListener('beforeunload',()=>save());
document.addEventListener('click',async e=>{if(!e.target.closest('#export-glb'))return;if(!scene){toast('GLB export needs WebGL. Try a browser with 3D support.');return;}try{toast('Preparing your 3D model…');const data=await scene.exportGLB();download(data,`${slug()}-model.glb`,'model/gltf-binary');toast('3D model exported.');}catch(err){console.warn('GLB export failed',err);toast('Could not export this model. Your project backup is still available.');}});

const studioBridge={getProject:()=>project,getFloor:floor,getFloorId:()=>floorId,getScene:()=>scene,getHomeSelection:()=>selected,mutate:fn=>commit(()=>fn(project)),render:renderAll,renderPlan,restoreInspector:renderInspector,setView,clearSelection:()=>{selected=null;scene?.updateSelection(null);},setFloor:id=>{floorId=id;selected=null;renderAll();},toast,modal,confirm:confirmDialog,download,slug,formatLength:length,replaceProject:p=>{project=validateProject(p);floorId=p.floors[0].id;selected=null;pendingPoint=null;planZoom=1;planCenter=null;history.undoStack=[];history.redoStack=[];save();renderAll();scene?.home();},getWorkspace:()=>localWorkspace,leaveCAD:()=>cadStudio?.deactivate(),leaveInterior:()=>interiorStudio?.deactivate()};
localWorkspace=mountLocalWorkspace(studioBridge);
cadStudio=mountCADStudio(studioBridge);
interiorStudio=mountInteriorStudio(studioBridge);
planningStudio=mountPlanningStudio(studioBridge);

mountTourStudio(studioBridge);
